css:
:where(.wtyg-map-site_animal_sacrifice) *{margin: 0; padding: 0; box-sizing: border-box;}
:where(.wtyg-map-site_animal_sacrifice),:where(.wtyg-map-site_animal_sacrifice){width: 100%;
            height: 100%;
            overflow: hidden;
            font-family: Arial, sans-serif;
            background: #1a1a1a;
            color: #fff;}
:where(.wtyg-map-site_animal_sacrifice) .map-wrapper{position: relative;
            width: 100%;
            height: 600px;
            overflow: hidden;}
:where(.wtyg-map-site_animal_sacrifice) :is([data-wtyg-id="map"],#wtyg-noid-map){width: 100%;
            height: 100%;
            background: #333;}
:where(.wtyg-map-site_animal_sacrifice) .info-panel{position: absolute;
            top: 10px;
            left: 10px;
            background: rgba(0,0,0,0.8);
            padding: 15px;
            border-radius: 8px;
            z-index: 1000;
            max-width: 300px;}
:where(.wtyg-map-site_animal_sacrifice) .info-panel h2{margin: 0 0 5px 0;
            font-size: 18px;
            color: #fff;}
:where(.wtyg-map-site_animal_sacrifice) .info-panel p{margin: 0;
            font-size: 12px;
            color: #ccc;}
:where(.wtyg-map-site_animal_sacrifice) .filters{margin-top: 10px;
            display: flex;
            flex-wrap: wrap;
            gap: 5px;}
:where(.wtyg-map-site_animal_sacrifice) .filter-btn{background: #444;
            border: 1px solid #666;
            color: #fff;
            padding: 5px 10px;
            border-radius: 15px;
            cursor: pointer;
            font-size: 11px;
            transition: all 0.2s;}
:where(.wtyg-map-site_animal_sacrifice) .filter-btn:hover{background: #555;}
:where(.wtyg-map-site_animal_sacrifice) .filter-btn.active{background: #4CAF50; border-color: #4CAF50;}
:where(.wtyg-map-site_animal_sacrifice) .stats{position: absolute;
            bottom: 10px;
            left: 10px;
            background: rgba(0,0,0,0.8);
            padding: 10px 15px;
            border-radius: 8px;
            z-index: 1000;
            font-size: 14px;}
:where(.wtyg-map-site_animal_sacrifice) .stats div{margin: 3px 0;}
:where(.wtyg-map-site_animal_sacrifice) .stats strong{color: #4CAF50;}
:where(.wtyg-map-site_animal_sacrifice) .marker-islamic{background: rgba(76,175,80,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-hindu{background: rgba(255,152,0,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-afrocaribbean{background: rgba(244,67,54,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-jewish{background: rgba(33,150,243,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-yoruba{background: rgba(156,39,176,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-african{background: rgba(255,87,34,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-pacific{background: rgba(0,188,212,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-shamanic{background: rgba(0,150,136,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-orthodox{background: rgba(121,85,72,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-armenian{background: rgba(205,92,92,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-chinese{background: rgba(255,193,7,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-malagasy{background: rgba(139,69,19,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-andean{background: rgba(184,134,11,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-mongolian{background: rgba(103,58,183,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .marker-shinto{background: rgba(233,30,99,0.9);}
:where(.wtyg-map-site_animal_sacrifice) .custom-marker{border: 2px solid #fff;
            border-radius: 50%;
            width: 12px;
            height: 12px;}
:where(.wtyg-map-site_animal_sacrifice) .leaflet-popup-content-wrapper{background: rgba(0,0,0,0.95);
            color: #fff;
            border-radius: 8px;}
:where(.wtyg-map-site_animal_sacrifice) .leaflet-popup-content{margin: 12px; font-size: 13px;}
:where(.wtyg-map-site_animal_sacrifice) .popup-title{font-weight: bold; font-size: 14px; margin-bottom: 5px; color: #4CAF50;}
:where(.wtyg-map-site_animal_sacrifice) .popup-location{margin-bottom: 5px;}
:where(.wtyg-map-site_animal_sacrifice) .popup-sources{font-size: 11px; color: #aaa; margin-top: 8px; padding-top: 8px; border-top: 1px solid #444;}
:where(.wtyg-map-site_animal_sacrifice) :is([data-wtyg-id="loading"],#wtyg-noid-loading){position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            z-index: 2000;
            background: rgba(0,0,0,0.9);
            padding: 20px;
            border-radius: 8px;
            color: #fff;}
